CREATE TABLE purchase_orders (id SERIAL PRIMARY KEY, order_id VARCHAR(40) UNIQUE NOT NULL, product VARCHAR(80) NOT NULL, store VARCHAR(40) NOT NULL, retailer VARCHAR(120), factory VARCHAR(120), quantity INTEGER NOT NULL, priority VARCHAR(30), status VARCHAR(40), created_at TIMESTAMP, expected_date VARCHAR(20));
CREATE TABLE production_orders (id SERIAL PRIMARY KEY, order_id VARCHAR(40) UNIQUE NOT NULL, product VARCHAR(80) NOT NULL, order_quantity INTEGER, finished_stock INTEGER, production_required INTEGER, capacity INTEGER, raw_material_status VARCHAR(40), recommendation TEXT, status VARCHAR(40), updated_at TIMESTAMP);
CREATE TABLE customer_feedback (id SERIAL PRIMARY KEY, product VARCHAR(80) NOT NULL, rating INTEGER, feedback TEXT NOT NULL, sentiment VARCHAR(30), created_at TIMESTAMP);
